parameters.jsCode:
// Assembles the caption list for the email. This node DELIBERATELY never
// touches the approval token — the raw token is injected only at the Resend
// node, direct from Issue Token. Keeping it out of here honours the design
// rule: the token exists in exactly two places, the Postgres response and the
// email body, and never in a Code node output.

const p = $input.item.json;
const posts = Array.isArray(p.posts) ? p.posts : [];

const LABEL = { instagram: 'Instagram', facebook: 'Facebook', linkedin: 'LinkedIn', tiktok: 'TikTok' };

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const propertyLabel =
  [p.title, p.municipality, p.canton].filter(Boolean).join(', ') || 'Ihre Immobilie';

const postsHtml = posts.map((po) => `
  <div style="border:1px solid #e5e5e5;border-radius:8px;padding:16px;margin:0 0 16px;">
    <div style="font-weight:600;font-size:13px;letter-spacing:0.02em;text-transform:uppercase;color:#6b6b6b;margin-bottom:8px;">${esc(LABEL[po.platform] || po.platform)}</div>
    <div style="white-space:pre-wrap;font-size:14px;line-height:1.55;color:#222;">${esc(po.caption)}</div>
  </div>`).join('');

const n = posts.length;
const subject = `${n} Caption${n === 1 ? '' : 's'} bereit zur Freigabe \u2013 ${propertyLabel}`;

return { json: {
  agent_email: p.agent_email,
  agent_name: p.agent_name || '',
  property_label: propertyLabel,
  post_count: n,
  posts_html: postsHtml,
  subject
} };

parameters.jsonBody:
={{ (() => {
  const BASE = 'https://supabase.alpinach.com/functions/v1/REPLACE_WITH_APPROVAL_FUNCTION';
  const token = $('Issue Token').item.json.token;
  const approveUrl = BASE + '/approve?token=' + token;
  const rejectUrl  = BASE + '/reject?token=' + token;
  const greeting = $json.agent_name ? ('Guten Tag ' + $json.agent_name) : 'Guten Tag';
  const html = `<!doctype html><html><body style="margin:0;padding:0;background:#f4f4f5;">
  <div style="max-width:600px;margin:0 auto;padding:32px 24px;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;">
    <h1 style="font-size:20px;color:#111;margin:0 0 8px;">${greeting},</h1>
    <p style="font-size:15px;line-height:1.55;color:#444;margin:0 0 24px;">Ihre ${$json.post_count} Caption${$json.post_count === 1 ? '' : 's'} f\u00fcr <strong>${$json.property_label}</strong> sind bereit. Bitte pr\u00fcfen Sie den Text und geben Sie ihn frei oder fordern Sie eine \u00dcberarbeitung an.</p>
    ${$json.posts_html}
    <div style="margin:28px 0 8px;">
      <a href="${approveUrl}" style="display:inline-block;background:#111;color:#fff;text-decoration:none;font-size:15px;font-weight:600;padding:14px 28px;border-radius:8px;">Alle freigeben</a>
      <a href="${rejectUrl}" style="display:inline-block;margin-left:12px;background:#fff;color:#111;text-decoration:none;font-size:15px;font-weight:600;padding:14px 28px;border-radius:8px;border:1px solid #d4d4d8;">Ablehnen / \u00dcberarbeiten</a>
    </div>
    <p style="font-size:13px;line-height:1.5;color:#8a8a8a;margin:24px 0 0;">Dieser Link ist 48 Stunden g\u00fcltig und kann nur einmal verwendet werden. Wenn Sie diese Anfrage nicht erwartet haben, ignorieren Sie diese E-Mail.</p>
  </div>
</body></html>`;
  return JSON.stringify({
    from: 'Alpinach <approvals@alpinach.com>',
    to: [$json.agent_email],
    subject: $json.subject,
    html
  });
})() }}
